// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log log_;
    function setUp() public { log_ = new Log(); c = new X_WALLET(address(log_)); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep params in the admissible domain (wide enough for the fuzzer)
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);

        // drive a single deposit through Put
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // general rule: after exactly one successful Put by `actor` of `amount`,
        // the log's first History entry records that depositor and that amount.
        bool ok;
        try log_.History(0) returns (address sender, string memory, uint256 val, uint256) {
            ok = (sender == actor && val == amount);
        } catch {
            // no entry was appended at all
            ok = false;
        }
        assertTrue(ok);
    }
}
